class Solution {
public:
    int longestWPI(vector<int>& hours) {
        map<int, int> first;
        int score = 0, best = 0;
        for (int i = 0; i < (int)hours.size(); i++) {
            score += hours[i] > 8 ? 1 : -1;
            if (score > 0) best = i + 1;
            else {
                if (!first.count(score)) first[score] = i;
                if (first.count(score - 1)) best = max(best, i - first[score - 1]);
            }
        }
        return best;
    }
};
